export const TYPES={goku:{name:'Goku',title:'Saiyajin · energia',power:'Kamehameha',cost:350,hp:430,damage:34,range:1.7,speed:2.5,cooldown:.72,special:8,color:0x60dcff},naruto:{name:'Naruto',title:'Ninja · clones',power:'Rasengan + clones',cost:250,hp:320,damage:23,range:1.5,speed:3.1,cooldown:.56,special:6,color:0x78beff},luffy:{name:'Luffy',title:'Pirata · impacto',power:'Gomu Gomu',cost:300,hp:520,damage:42,range:2.7,speed:2.2,cooldown:1,special:7,color:0xffd96a}};
export const CHALLENGES=[{name:'Primeiro confronto',budget:850,enemies:[['naruto',3,0],['luffy',5,2]]},{name:'Rajadas cruzadas',budget:1200,enemies:[['goku',5,-3],['goku',5,3],['naruto',2,0]]},{name:'Maré de clones',budget:1500,enemies:[['naruto',3,-4],['naruto',3,0],['naruto',3,4],['naruto',6,-2],['naruto',6,2]]},{name:'Linha de frente',budget:1900,enemies:[['luffy',2,-3],['luffy',2,0],['luffy',2,3],['goku',6,-2],['goku',6,2]]},{name:'Caos total',budget:2400,enemies:[['goku',5,-4],['goku',5,4],['luffy',2,-2],['luffy',2,2],['naruto',5,0],['naruto',7,-2],['naruto',7,2]]}];
export class Battle{constructor(formation,onEvent=()=>{},random=Math.random){this.random=random;this.onEvent=onEvent;this.time=0;this.finished=false;this.winner=null;this.units=formation.map((f,i)=>({...f,id:i,hp:TYPES[f.type].hp,maxHp:TYPES[f.type].hp,cool:random()*.5,special:2+random()*3,hit:0,attack:0,dead:0,vx:0,vz:0}));}damage(u,n,source){if(u.hp<=0)return;u.hp=Math.max(0,u.hp-n);u.hit=.2;const dx=u.x-source.x,dz=u.z-source.z,len=Math.hypot(dx,dz)||1;u.vx+=dx/len*1.8;u.vz+=dz/len*1.8;if(!u.hp)this.onEvent({type:'death',unit:u,source});}
step(dt){if(this.finished)return;this.time+=dt;const live=this.units.filter(u=>u.hp>0);for(const u of this.units){u.hit=Math.max(0,u.hit-dt);u.attack=Math.max(0,u.attack-dt);if(!u.hp){u.dead+=dt;continue;}u.cool-=dt;u.special-=dt;const def=TYPES[u.type];let target,dist=Infinity;for(const v of live){if(v.team===u.team||v.hp<=0)continue;const d=Math.hypot(v.x-u.x,v.z-u.z);if(d<dist){dist=d;target=v;}}if(!target)continue;u.angle=Math.atan2(target.x-u.x,target.z-u.z);u.x+=u.vx*dt;u.z+=u.vz*dt;u.vx*=Math.exp(-8*dt);u.vz*=Math.exp(-8*dt);if(dist>def.range){u.x+=Math.sin(u.angle)*def.speed*dt;u.z+=Math.cos(u.angle)*def.speed*dt;}else if(u.cool<=0){u.cool=def.cooldown;u.attack=.28;this.damage(target,def.damage,u);this.onEvent({type:'hit',unit:u,target});}if(u.special<=0&&dist<10){u.special=def.special;u.attack=.65;const victims=live.filter(v=>v.team!==u.team&&v.hp>0);if(u.type==='goku'){for(const v of victims){const dx=v.x-u.x,dz=v.z-u.z,along=dx*Math.sin(u.angle)+dz*Math.cos(u.angle),across=Math.abs(dx*Math.cos(u.angle)-dz*Math.sin(u.angle));if(along>0&&along<14&&across<1.6)this.damage(v,125,u);}}else if(u.type==='naruto'){this.damage(target,95,u);for(const v of victims)if(v!==target&&Math.hypot(v.x-target.x,v.z-target.z)<2.5)this.damage(v,35,u);}else{for(const v of victims)if(Math.hypot(v.x-u.x,v.z-u.z)<5){this.damage(v,85,u);v.vx+=Math.sin(u.angle)*6;v.vz+=Math.cos(u.angle)*6;}}this.onEvent({type:'special',unit:u,target,angle:u.angle});}u.x=Math.max(-11,Math.min(11,u.x));u.z=Math.max(-7,Math.min(7,u.z));}
// Symmetric positional separation prevents stacked units without changing damage.
for(let i=0;i<live.length;i++)for(let j=i+1;j<live.length;j++){const a=live[i],b=live[j];if(a.hp<=0||b.hp<=0)continue;const dx=b.x-a.x,dz=b.z-a.z,d=Math.hypot(dx,dz);if(d<.75){const nx=d>0?dx/d:1,nz=d>0?dz/d:0,s=(.75-d)*.5;a.x-=nx*s;a.z-=nz*s;b.x+=nx*s;b.z+=nz*s;}}
const teams=new Set(this.units.filter(u=>u.hp>0).map(u=>u.team));if(teams.size<2||this.time>=120){this.finished=true;this.winner=teams.size===1?[...teams][0]:null;this.onEvent({type:'finish',winner:this.winner});}}
}
